import pandas as pd
import matplotlib.pyplot as plt
import base64
from io import BytesIO
import numpy as np

def clean_eccentricity(val):
    if isinstance(val, str):
        if val.startswith('.'):
            return float('0' + val)
    return float(val)

def generate_charts(df):
    charts = {}

    # 1. Launch Year Trends
    plt.figure(figsize=(10, 6))
    launch_counts = df['LAUNCH_YEAR'].value_counts().sort_index()
    # Only show last 30 years or so to make it readable, or all? Let's show all
    launch_counts.plot(kind='bar', width=0.8, color='#1f77b4')
    plt.title('Active Satellites by Launch Year', fontsize=14)
    plt.xlabel('Launch Year')
    plt.ylabel('Count')
    plt.xticks(rotation=45)
    plt.grid(axis='y', linestyle='--', alpha=0.7)
    plt.tight_layout()
    buf = BytesIO()
    plt.savefig(buf, format='png')
    plt.close()
    charts['launch_trend'] = base64.b64encode(buf.getvalue()).decode('utf-8')

    # 2. Orbital Regimes
    plt.figure(figsize=(8, 8))
    regime_counts = df['REGIME'].value_counts()
    plt.pie(regime_counts, labels=regime_counts.index, autopct='%1.1f%%', startangle=140, colors=['#ff9999','#66b3ff','#99ff99','#ffcc99'])
    plt.title('Distribution by Orbital Regime', fontsize=14)
    plt.tight_layout()
    buf = BytesIO()
    plt.savefig(buf, format='png')
    plt.close()
    charts['regimes'] = base64.b64encode(buf.getvalue()).decode('utf-8')

    # 3. Top Constellations
    plt.figure(figsize=(10, 6))
    top_const = df['CONSTELLATION'].value_counts().head(10)
    top_const.plot(kind='barh', color='#2ca02c')
    plt.title('Top 10 Satellite Constellations / Operators', fontsize=14)
    plt.xlabel('Number of Satellites')
    plt.gca().invert_yaxis()
    plt.tight_layout()
    buf = BytesIO()
    plt.savefig(buf, format='png')
    plt.close()
    charts['constellations'] = base64.b64encode(buf.getvalue()).decode('utf-8')

    # 4. Mean Motion vs Inclination
    plt.figure(figsize=(10, 6))
    plt.scatter(df['INCLINATION'], df['MEAN_MOTION'], alpha=0.1, s=10, c='#d62728')
    plt.title('Mean Motion vs Inclination', fontsize=14)
    plt.xlabel('Inclination (degrees)')
    plt.ylabel('Mean Motion (revs/day)')
    plt.grid(True, linestyle='--', alpha=0.7)
    plt.tight_layout()
    buf = BytesIO()
    plt.savefig(buf, format='png')
    plt.close()
    charts['orbital'] = base64.b64encode(buf.getvalue()).decode('utf-8')

    return charts

def main():
    df = pd.read_csv('/app/benchmark/data.csv')

    # Data Cleaning
    df['ECCENTRICITY_NUM'] = df['ECCENTRICITY'].apply(clean_eccentricity)
    df['LAUNCH_YEAR'] = df['OBJECT_ID'].astype(str).str[:4].astype(int)

    # Orbital Regime Classification
    def classify_regime(row):
        mm = row['MEAN_MOTION']
        ecc = row['ECCENTRICITY_NUM']
        if ecc > 0.25:
            return 'HEO'
        elif mm >= 11.25:
            return 'LEO'
        elif 0.9 <= mm <= 1.1:
            return 'GEO'
        else:
            return 'MEO'

    df['REGIME'] = df.apply(classify_regime, axis=1)

    # Constellation Extraction
    def extract_constellation(name):
        name = str(name).upper()
        if 'STARLINK' in name: return 'STARLINK'
        if 'ONEWEB' in name: return 'ONEWEB'
        if 'FLOCK' in name: return 'FLOCK (PLANET)'
        if 'LEMUR' in name: return 'LEMUR (SPIRE)'
        if 'IRIDIUM' in name: return 'IRIDIUM'
        if 'GLOBALSTAR' in name: return 'GLOBALSTAR'
        if 'GPS' in name or 'NAVSTAR' in name: return 'GPS'
        if 'GALILEO' in name: return 'GALILEO'
        if 'GLONASS' in name or 'COSMOS' in name and 'GLONASS' in name: return 'GLONASS' # Simple approx
        if 'BEIDOU' in name or 'COMPASS' in name: return 'BEIDOU'
        if 'SPACEBEE' in name: return 'SPACEBEE'
        if 'O3B' in name: return 'O3B'
        parts = name.split()
        if len(parts) > 0:
            # check for dash or space
            if '-' in parts[0]:
                return parts[0].split('-')[0]
            return parts[0]
        return 'OTHER'

    df['CONSTELLATION'] = df['OBJECT_NAME'].apply(extract_constellation)

    # KPIs
    total_satellites = len(df)
    leo_share = (len(df[df['REGIME'] == 'LEO']) / total_satellites) * 100
    starlink_count = len(df[df['OBJECT_NAME'].astype(str).str.startswith('STARLINK')])
    median_inclination = df['INCLINATION'].median()
    post_2020_count = len(df[df['LAUNCH_YEAR'] >= 2020])

    # Generate Charts
    charts = generate_charts(df)

    # Generate HTML
    html = f'''
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>Active Satellites in Earth Orbit — 2026 Catalog Analysis</title>
        <style>
            :root {{
                --primary: #1e3a8a;
                --secondary: #3b82f6;
                --background: #f8fafc;
                --surface: #ffffff;
                --text: #0f172a;
                --text-light: #64748b;
                --border: #e2e8f0;
            }}
            body {{
                font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
                background-color: var(--background);
                color: var(--text);
                line-height: 1.6;
                margin: 0;
                padding: 0;
            }}
            .container {{
                max-width: 1200px;
                margin: 0 auto;
                padding: 40px 20px;
            }}
            header {{
                text-align: center;
                margin-bottom: 50px;
            }}
            h1 {{
                color: var(--primary);
                font-size: 2.5rem;
                margin-bottom: 10px;
            }}
            .subtitle {{
                font-size: 1.2rem;
                color: var(--text-light);
            }}
            .kpi-container {{
                display: flex;
                flex-wrap: wrap;
                gap: 20px;
                margin-bottom: 40px;
            }}
            .kpi-card {{
                background: var(--surface);
                border-radius: 12px;
                padding: 25px;
                flex: 1;
                min-width: 200px;
                box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
                border: 1px solid var(--border);
                text-align: center;
            }}
            .kpi-value {{
                font-size: 2.2rem;
                font-weight: 700;
                color: var(--secondary);
                margin-bottom: 8px;
            }}
            .kpi-label {{
                font-size: 0.9rem;
                color: var(--text-light);
                text-transform: uppercase;
                letter-spacing: 0.05em;
            }}
            section {{
                background: var(--surface);
                border-radius: 12px;
                padding: 30px;
                margin-bottom: 30px;
                box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
                border: 1px solid var(--border);
            }}
            h2 {{
                color: var(--primary);
                border-bottom: 2px solid var(--border);
                padding-bottom: 10px;
                margin-top: 0;
                margin-bottom: 20px;
            }}
            .chart-container {{
                text-align: center;
                margin: 20px 0;
            }}
            .chart-container img {{
                max-width: 100%;
                height: auto;
                border-radius: 8px;
                border: 1px solid var(--border);
            }}
            .grid-2 {{
                display: grid;
                grid-template-columns: 1fr 1fr;
                gap: 30px;
            }}
            @media (max-width: 768px) {{
                .grid-2 {{
                    grid-template-columns: 1fr;
                }}
            }}
            p {{
                margin-bottom: 15px;
            }}
        </style>
    </head>
    <body>
        <div class="container">
            <header>
                <h1>Active Satellites in Earth Orbit</h1>
                <div class="subtitle">2026 Catalog Analysis</div>
            </header>

            <div class="kpi-container">
                <div class="kpi-card">
                    <div class="kpi-value">{total_satellites:,}</div>
                    <div class="kpi-label">Total Active Satellites</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-value">{leo_share:.1f}%</div>
                    <div class="kpi-label">LEO Share</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-value">{starlink_count:,}</div>
                    <div class="kpi-label">Starlink Constellation Size</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-value">{median_inclination:.1f}&deg;</div>
                    <div class="kpi-label">Median Inclination</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-value">{post_2020_count:,}</div>
                    <div class="kpi-label">Satellites Launched Since 2020</div>
                </div>
            </div>

            <section id="overview">
                <h2>Catalog Overview & Key Figures</h2>
                <p>This report analyzes the current operational satellite catalog based on TLE data from the CelesTrak platform. The dataset covers <strong>{total_satellites:,}</strong> active objects. The median orbital inclination across all satellites is <strong>{median_inclination:.1f}&deg;</strong>, reflecting the prevalence of mid-to-high inclination orbits suited for global coverage. The catalog demonstrates a staggering acceleration in launch activity, with <strong>{post_2020_count:,}</strong> satellites (roughly {(post_2020_count/total_satellites)*100:.1f}%) having been launched in or after 2020.</p>
            </section>

            <div class="grid-2">
                <section id="launch-trends">
                    <h2>Launch Year Trends</h2>
                    <p>The headline story in the satellite industry is the dramatic inflection point in launch activity over the past half-decade. Driven by the deployment of mega-constellations and a reduction in launch costs, the number of currently active satellites placed in orbit annually has skyrocketed.</p>
                    <div class="chart-container">
                        <img src="data:image/png;base64,{charts['launch_trend']}" alt="Launch Year Trends">
                    </div>
                </section>

                <section id="orbit-regime">
                    <h2>Orbital Regime Classification</h2>
                    <p>The orbital environment is overwhelmingly dominated by Low Earth Orbit (LEO) systems. By classifying objects based on Mean Motion (revolutions per day) and Eccentricity, we find that LEO systems constitute <strong>{leo_share:.1f}%</strong> of the active catalog.</p>
                    <ul>
                        <li><strong>LEO (Low Earth Orbit):</strong> >11.25 rev/day</li>
                        <li><strong>MEO (Medium Earth Orbit):</strong> Between LEO and GEO</li>
                        <li><strong>GEO (Geosynchronous Orbit):</strong> ~1.0 rev/day</li>
                        <li><strong>HEO (Highly Elliptical Orbit):</strong> Eccentricity > 0.25</li>
                    </ul>
                    <div class="chart-container">
                        <img src="data:image/png;base64,{charts['regimes']}" alt="Orbital Regimes">
                    </div>
                </section>
            </div>

            <div class="grid-2">
                <section id="constellation-analysis">
                    <h2>Major Constellation & Operator Breakdown</h2>
                    <p>SpaceX's Starlink constellation reshapes the entire statistical picture of the orbital environment. With <strong>{starlink_count:,}</strong> operational satellites, Starlink accounts for nearly {(starlink_count/total_satellites)*100:.1f}% of all active satellites. Other major contributors include OneWeb, Planet's Flock, and Spire's Lemur systems.</p>
                    <div class="chart-container">
                        <img src="data:image/png;base64,{charts['constellations']}" alt="Major Constellations">
                    </div>
                </section>

                <section id="orbital-characteristics">
                    <h2>Orbital Parameter Deep Dive</h2>
                    <p>The distribution of Mean Motion versus Inclination highlights dense "orbital shells." Starlink and other mega-constellations form distinct horizontal bands (indicating consistent altitude/mean motion) across a few key inclinations (e.g., 53&deg;, 70&deg;, 97&deg; SSO). Geostationary satellites form a cluster near 0&deg; inclination and 1.0 rev/day mean motion.</p>
                    <div class="chart-container">
                        <img src="data:image/png;base64,{charts['orbital']}" alt="Orbital Characteristics">
                    </div>
                </section>
            </div>

            <section id="conclusions">
                <h2>Key Takeaways & Outlook</h2>
                <p><strong>1. Unprecedented Growth:</strong> The exponential growth curve in launch volume over the past five years indicates a structural shift in how space is utilized, moving from bespoke, large-scale satellites to mass-produced LEO constellations.</p>
                <p><strong>2. The LEO Congestion:</strong> With over {leo_share:.1f}% of active objects in LEO, the lower orbital regimes are becoming increasingly dense. This necessitates advanced space traffic management and stricter orbital debris mitigation protocols.</p>
                <p><strong>3. Monopolization of Orbit:</strong> A single operator, SpaceX, dominates the catalog. This skew heavily influences global statistics and underscores the regulatory and spectrum allocation challenges facing policy advisors in the near future.</p>
                <p><strong>4. Orbital Shell Density:</strong> Specific orbital parameters—namely, mid-inclination LEO bands and Sun-Synchronous Orbits (SSO) around 97-98 degrees—are highly sought after and represent the most congested "highways" in space.</p>
            </section>
        </div>
    </body>
    </html>
    '''

    with open('/app/output/final_report.html', 'w') as f:
        f.write(html)

if __name__ == '__main__':
    main()
